#include "space_invaders/gui.h"
#include <SDL.h>
static void block(SDL_Renderer*r,int x,int y,int w,int h,SDL_Color c){SDL_SetRenderDrawColor(r,c.r,c.g,c.b,255);SDL_Rect q{x,y,w,h};SDL_RenderFillRect(r,&q);}
void gui_render(const Gui*g,const Game*x){SDL_SetRenderDrawColor(g->renderer,8,12,30,255);SDL_RenderClear(g->renderer);constexpr int c=24,l=192,t=72;for(int i=0;i<GAME_WIDTH;i++)for(int j=0;j<GAME_HEIGHT;j++)if((i+j)%7==0)block(g->renderer,l+i*c,t+j*c,2,2,{40,55,90,255});for(int s=0;s<SHIELD_COUNT;s++)for(int k=0;k<SHIELD_WIDTH;k++)if(x->shields[s][k])block(g->renderer,l+(s*16+k*2)*c,t+SHIELD_ROW*c,c*2-3,c-4,{90,190,150,255});if(x->bonus_active)block(g->renderer,l+x->bonus_x*c,t+8,c*5-4,c-4,{250,190,70,255});SDL_Color enemy=x->room_type==ROOM_ELITE?SDL_Color{255,80,180,255}:x->room_type==ROOM_CACHE?SDL_Color{120,180,255,255}:SDL_Color{235,75,110,255};block(g->renderer,l+x->alien*c,t+x->alien_row*c,c*3-4,c-4,enemy);for(int i=0;i<x->alien_hp;i++)block(g->renderer,l+x->alien*c+i*7,t-10,5,4,{255,235,120,255});block(g->renderer,l+x->player*c,t+(GAME_HEIGHT-1)*c,c*3-4,c-4,{65,220,180,255});if(x->bullet>=0)block(g->renderer,l+(x->player+1)*c+8,t+x->bullet*c,4,c-4,{250,235,120,255});if(x->enemy_bullet>=0)block(g->renderer,l+(x->alien+1)*c+8,t+x->enemy_bullet*c,4,c-4,{255,110,80,255});for(int i=0;i<x->lives;i++)block(g->renderer,24+i*20,24,12,8,{65,220,180,255});for(int i=0;i<x->wave;i++)block(g->renderer,800+i*10,24,6,8,{235,75,110,255});int m=x->ai_mood<0?-x->ai_mood:x->ai_mood;block(g->renderer,420,24,m>100?100:m,8,x->ai_mood<0?SDL_Color{80,150,255,255}:SDL_Color{255,100,130,255});if(x->paused||x->over)block(g->renderer,430,300,100,20,x->over?SDL_Color{235,75,110,255}:SDL_Color{250,235,120,255});SDL_RenderPresent(g->renderer);}
